    def makesquare(self, matchsticks):
        """
        :type matchsticks: List[int]
        :rtype: bool
        """
        sum_length = sum(matchsticks)
        if sum_length % 4:
            return False
        matchsticks.sort(reverse=True)

        edges = [0 for _ in range(4)]
        def dfs(idx):
            if idx == len(matchsticks):
                return True
            for i in range(4):
